CREATE OR REPLACE FUNCTION public.feya_commerce_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_commerce_touch_updated_at_v1()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_fn_guard_execution_request_material_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if public.feya_fn_execution_request_material_json_v1(old)
     is distinct from public.feya_fn_execution_request_material_json_v1(new) then
    raise exception 'Execution request material fields are immutable; create a new request';
  end if;

  return new;
end;
$function$
